CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, xp INT NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE challenges (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, difficulty VARCHAR(255) NOT NULL, context VARCHAR(2000) NOT NULL, expected_output_format VARCHAR(64) NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE challenge_requirements (challenge_id BIGINT NOT NULL, requirement VARCHAR(500) NOT NULL, CONSTRAINT fk_requirement_challenge FOREIGN KEY (challenge_id) REFERENCES challenges(id));
CREATE TABLE challenge_constraints (challenge_id BIGINT NOT NULL, constraint_text VARCHAR(500) NOT NULL, CONSTRAINT fk_constraint_challenge FOREIGN KEY (challenge_id) REFERENCES challenges(id));
CREATE TABLE challenge_acceptance_criteria (challenge_id BIGINT NOT NULL, criterion VARCHAR(500) NOT NULL, CONSTRAINT fk_criterion_challenge FOREIGN KEY (challenge_id) REFERENCES challenges(id));
CREATE TABLE submissions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, challenge_id BIGINT NOT NULL, answer VARCHAR(10000) NOT NULL, submitted_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_submission_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_submission_challenge FOREIGN KEY (challenge_id) REFERENCES challenges(id));
CREATE TABLE evaluations (id BIGINT AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT NOT NULL UNIQUE, requirement_understanding DOUBLE NOT NULL, logical_clarity DOUBLE NOT NULL, technical_feasibility DOUBLE NOT NULL, edge_case_coverage DOUBLE NOT NULL, communication_structure DOUBLE NOT NULL, final_score DOUBLE NOT NULL, feedback VARCHAR(5000) NOT NULL, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_evaluation_submission FOREIGN KEY (submission_id) REFERENCES submissions(id));
